'use strict';
const blogSearch=document.querySelector('#storySearch');let storyCategory='All';
function filterStories(){let count=0;const q=blogSearch.value.trim().toLowerCase();document.querySelectorAll('.story-card[data-category]').forEach(card=>{const visible=(storyCategory==='All'||card.dataset.category===storyCategory)&&card.dataset.search.includes(q);card.hidden=!visible;if(visible)count++});document.querySelector('#storyCount').textContent=count+' '+(count===1?'story':'stories');document.querySelector('#noStories').hidden=count>0;document.querySelectorAll('[data-story-cat]').forEach(b=>{const active=b.dataset.storyCat===storyCategory;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)})}
if(blogSearch){blogSearch.addEventListener('input',filterStories);document.querySelectorAll('[data-story-cat]').forEach(b=>b.onclick=()=>{storyCategory=b.dataset.storyCat;filterStories()});document.querySelector('#resetStories').onclick=()=>{blogSearch.value='';storyCategory='All';filterStories()}}
const copyArticle=document.querySelector('#copyArticle');if(copyArticle)copyArticle.onclick=async()=>{const status=document.querySelector('#copyStatus');try{await navigator.clipboard.writeText(location.href);status.textContent='Article link copied.'}catch{status.textContent='Copy the article URL from your browser’s address bar.'}status.style.display='block';setTimeout(()=>status.style.display='none',3500)};
